typedef enum CaDigestType {
        CA_DIGEST_SHA256,
        CA_DIGEST_SHA512_256,
        _CA_DIGEST_TYPE_MAX,
        CA_DIGEST_DEFAULT = CA_DIGEST_SHA512_256,
        _CA_DIGEST_TYPE_INVALID = -1,
} CaDigestType;

typedef union CaChunkID {
        /* Depending on context either a SHA256 or SHA512/256 sum */
        uint8_t bytes[CA_CHUNK_ID_SIZE];
        uint64_t u64[CA_CHUNK_ID_SIZE / sizeof(uint64_t)];
} CaChunkID;

