import os
import random
import struct
from typing import List

# Generator for arbitrary binary data tailored to exercise digest and chunk-id code paths.
# Produces valid arbitrary bytes with seeded randomness. Avoids invalid UTF-8 surrogate code points.

_MAX = 1024

def _rng(seed: int) -> random.Random:
    return random.Random(seed & 0xFFFFFFFF)

def _ascii_words(r: random.Random, n: int) -> bytes:
    words = [
        b"hello", b"world", b"compression", b"digest", b"sha256", b"sha512/256",
        b"chunk", b"id", b"zstd", b"gzip", b"xz", b"linux", b"systemd", b"cache",
        b"content-addressed", b"fuzz", b"test", b"data", b"binary", b"random"
    ]
    out = bytearray()
    while len(out) < n:
        w = r.choice(words)
        out.extend(w + b" ")
    return bytes(out[:n])

def _utf8_mix(r: random.Random, n: int) -> bytes:
    # Mix ASCII with multi-byte UTF-8 sequences, avoiding surrogate code points (U+D800..U+DFFF)
    parts = []
    total = 0
    while total < n:
        t = r.randrange(5)
        if t == 0:
            b = bytes([r.randrange(32, 127)])
        elif t == 1:
            cp = r.randrange(0x80, 0x800)
            b = chr(cp).encode('utf-8')
        elif t == 2:
            # pick BMP excluding surrogates
            while True:
                cp = r.randrange(0x80, 0x10000)
                if not (0xD800 <= cp <= 0xDFFF):
                    break
            b = chr(cp).encode('utf-8')
        elif t == 3:
            cp = r.randrange(0x10000, 0x110000)
            b = chr(cp).encode('utf-8')
        else:
            b = b"\n"
        parts.append(b)
        total += len(b)
    return b"".join(parts)[:n]

def _incremental(n: int, start: int = 0) -> bytes:
    return bytes(((start + i) & 0xFF) for i in range(n))

def _repeated_block(block: bytes, n: int) -> bytes:
    if not block:
        return b""
    reps = (n + len(block) - 1) // len(block)
    return (block * reps)[:n]

def _prime_lengths_upto(m: int) -> List[int]:
    sieve = [True] * (m + 1)
    if m >= 0:
        sieve[0] = False
    if m >= 1:
        sieve[1] = False
    p = 2
    while p * p <= m:
        if sieve[p]:
            for k in range(p * p, m + 1, p):
                sieve[k] = False
        p += 1
    return [i for i, v in enumerate(sieve) if v]

def _choose_length(r: random.Random) -> int:
    specials = [0, 1, 31, 32, 33, 63, 64, 65, 127, 128, 129, 255, 256, 257, _MAX]
    if r.random() < 0.6:
        return r.choice(specials)
    if r.random() < 0.2:
        k = r.choice([2,3,4,5,6,7,8,9,10])
        v = 1 << k
        return min(v, _MAX)
    if r.random() < 0.2:
        primes = _prime_lengths_upto(_MAX)
        return r.choice(primes)
    return r.randrange(0, _MAX + 1)

def _structured_random(r: random.Random, n: int) -> bytes:
    segs = []
    remaining = n
    while remaining > 0:
        seg_len = r.randrange(1, min(remaining, 128) + 1)
        kind = r.randrange(8)
        if kind == 0:
            seg = bytes([0]) * seg_len
        elif kind == 1:
            seg = bytes([0xFF]) * seg_len
        elif kind == 2:
            seg = os.urandom(seg_len)
        elif kind == 3:
            seg = _incremental(seg_len, r.randrange(256))
        elif kind == 4:
            blk = struct.pack('<I', r.getrandbits(32))
            seg = _repeated_block(blk, seg_len)
        elif kind == 5:
            seg = _ascii_words(r, seg_len)
        elif kind == 6:
            seg = _utf8_mix(r, seg_len)
        else:
            a = r.randrange(256)
            b = r.randrange(256)
            seg = bytes((a if (i & 1) == 0 else b) for i in range(seg_len))
        segs.append(seg)
        remaining -= seg_len
    return b"".join(segs)

def generate(seed: int) -> bytes:
    r = _rng(seed)
    n = _choose_length(r)
    if n == 0:
        return b""
    mode = r.randrange(7)
    if mode == 0:
        return bytes([0]) * n
    if mode == 1:
        return bytes([0xFF]) * n
    if mode == 2:
        return _incremental(n, r.randrange(256))
    if mode == 3:
        blk_size = r.choice([3,4,8,16,32,64])
        blk = os.urandom(blk_size)
        return _repeated_block(blk, n)
    if mode == 4:
        return _ascii_words(r, n)
    if mode == 5:
        return _utf8_mix(r, n)
    return _structured_random(r, n)
